vector<int> maxSlidingWindow(vector<int>& nums, int k) {
    deque<int> idx;   // stores indices, values in decreasing order
    vector<int> result;

    for (int i = 0; i < nums.size(); i++) {
        while (!idx.empty() && nums[idx.back()] < nums[i])
            idx.pop_back();
        idx.push_back(i);

        if (idx.front() <= i - k)
            idx.pop_front();

        if (i >= k - 1)
            result.push_back(nums[idx.front()]);
    }
    return result;
}

class LRUCache {
private:
    struct Node {
        int key, value;
        Node* prev;
        Node* next;
        Node(int k, int v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    int capacity;
    unordered_map<int, Node*> cache;
    Node* head;
    Node* tail;

    void insertAtFront(Node* node) {
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }

    void removeNode(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    void moveToFront(Node* node) {
        removeNode(node);
        insertAtFront(node);
    }

public:
    LRUCache(int cap) : capacity(cap) {
        head = new Node(-1, -1);
        tail = new Node(-1, -1);
        head->next = tail;
        tail->prev = head;
    }

    int get(int key) {
        if (cache.find(key) == cache.end()) return -1;
        Node* node = cache[key];
        moveToFront(node);
        return node->value;
    }

    void put(int key, int value) {
        if (cache.find(key) != cache.end()) {
            Node* node = cache[key];
            node->value = value;
            moveToFront(node);
            return;
        }

        if ((int)cache.size() == capacity) {
            Node* lru = tail->prev;
            removeNode(lru);
            cache.erase(lru->key);
            delete lru;
        }

        Node* node = new Node(key, value);
        cache[key] = node;
        insertAtFront(node);
    }
};

class RandomizedSet {
private:
    vector<int> values;
    unordered_map<int, int> indexOf;

public:
    bool insert(int val) {
        if (indexOf.count(val)) return false;
        indexOf[val] = values.size();
        values.push_back(val);
        return true;
    }

    bool remove(int val) {
        if (!indexOf.count(val)) return false;

        int idx = indexOf[val];
        int lastVal = values.back();

        values[idx] = lastVal;
        indexOf[lastVal] = idx;

        values.pop_back();
        indexOf.erase(val);
        return true;
    }

    int getRandom() {
        int idx = rand() % values.size();
        return values[idx];
    }
};
